  /**
   * Map layers, or nothing at all off a running game.
   *
   * Hidden rather than disabled: the rows are enumerated from the current
   * map's layer manifest, so with no game there is no list to grey out — a
   * disabled section here would be an empty box with a heading over it.
   */
  renderMapLayers() {
    if (this.mapLayers.length === 0) return lit.nothing;
    const layersOn = this.userSettings.mapLayers();
    return lit.html`
      <div data-map-layers>
        ${GraphicsAdvancedSettings.section("graphics_setting.section_map_layers")}
        ${this.mapLayers.map(layer => {
      const alpha = this.getLayerAlpha(layer.id, layer.alpha);
      return lit.html`
            <div class="flex flex-col gap-2">
              <setting-toggle
                label=${this.layerName(layer.id)}
                description=${`${layer.placement === "land" ? (0,Utils/* translateText */.O9)("graphics_setting.layer_placement_land") : (0,Utils/* translateText */.O9)("graphics_setting.layer_placement_water")}${layer.nukeable ? ` · ${(0,Utils/* translateText */.O9)("graphics_setting.layer_nukeable")}` : ""}`}
                id=${`map-layer-${layer.id}-toggle`}
                .checked=${this.isLayerVisible(layer.id)}
                ?disabled=${!layersOn}
                @change=${() => this.onToggleLayer(layer.id)}
              ></setting-toggle>
              ${layersOn && this.isLayerVisible(layer.id) ? lit.html`<setting-slider
                      label=${`${this.layerName(layer.id)} — ${(0,Utils/* translateText */.O9)("graphics_setting.layer_alpha_label")}`}
                      description=""
                      id=${`map-layer-${layer.id}-alpha-slider`}
                      min=${LAYER_ALPHA_MIN}
                      max=${LAYER_ALPHA_MAX}
                      step=${LAYER_ALPHA_STEP}
                      unit=""
                      .formatValue=${v => v.toFixed(2)}
                      .value=${alpha}
                      @change=${e => this.onLayerAlphaSliderChange(layer.id, e)}
                    ></setting-slider>` : lit.nothing}
            </div>
          `;
    })}
      </div>
    `;
  }
