// ---------------------------------------------------------------------------
// Draggable title bar
// ---------------------------------------------------------------------------

function makeDraggable(gui) {
  const titleBar = gui.domElement.querySelector(".title, .lil-title");
  if (!titleBar) return;
  titleBar.style.cursor = "grab";
  let dragging = false;
  let didDrag = false;
  let startX = 0,
    startY = 0,
    startLeft = 0,
    startTop = 0;
  titleBar.addEventListener("mousedown", e => {
    dragging = true;
    didDrag = false;
    titleBar.style.cursor = "grabbing";
    const rect = gui.domElement.getBoundingClientRect();
    startX = e.clientX;
    startY = e.clientY;
    startLeft = rect.left;
    startTop = rect.top;
    gui.domElement.style.left = rect.left + "px";
    gui.domElement.style.right = "auto";
    e.preventDefault();
  });
  window.addEventListener("mousemove", e => {
    if (!dragging) return;
    didDrag = true;
    gui.domElement.style.left = startLeft + e.clientX - startX + "px";
    gui.domElement.style.top = startTop + e.clientY - startY + "px";
  });
  window.addEventListener("mouseup", () => {
    if (!dragging) return;
    dragging = false;
    titleBar.style.cursor = "grab";
  });
  titleBar.addEventListener("click", e => {
    if (didDrag) e.stopPropagation();
  }, {
    capture: true
  });
}

